CREATE COLUMN TABLE "TEST_AP"."ASP1" ("ItemCode" NVARCHAR(50) NOT NULL , "CardCode" NVARCHAR(15) NOT NULL , "LINENUM" SMALLINT CS_INT NOT NULL , "Price" DECIMAL(21,6) CS_FIXED, "Currency" NVARCHAR(3), "Discount" DECIMAL(21,6) CS_FIXED, "ListNum" SMALLINT CS_INT DEFAULT 0, "FromDate" LONGDATE CS_LONGDATE, "ToDate" LONGDATE CS_LONGDATE, "AutoUpdt" NVARCHAR(1) DEFAULT 'Y', "Expand" NVARCHAR(1) DEFAULT 'N', "LogInstanc" INTEGER CS_INT DEFAULT 0 NOT NULL , PRIMARY KEY ("CardCode", "ItemCode", "LINENUM", "LogInstanc")) UNLOAD PRIORITY 5  AUTO MERGE 